static inline int sucs_ucd_block_lookup(sucs_char_t cp) {
    int lo = 0;
    int hi = SUCS_UCD_BLOCK_COUNT - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (cp < sucs_ucd_blocks[mid].min) {
            hi = mid - 1;
        } else if (cp > sucs_ucd_blocks[mid].max) {
            lo = mid + 1;
        } else {
            return mid;
        }
    }
    return -1;
}

static inline bool sucs_is_in_ucd_block(sucs_char_t cp, int block_index) {
    if (block_index < 0 || block_index >= SUCS_UCD_BLOCK_COUNT) return false;
    return (cp >= sucs_ucd_blocks[block_index].min && cp <= sucs_ucd_blocks[block_index].max);
}

